  default_level: "Warn",
  desc: "filtering `std::io::Lines` with `filter_map()`, `flat_map()`, or `flatten()` might cause an infinite loop",
  edition_lint_opts: undefined,
  report_in_external_macro: true,
  future_incompatible: undefined,
