/// Detect functions that end with `Option::and_then` or `Result::and_then`, and suggest using
/// the `?` operator instead.
///
/// ### Why is this bad?
/// The `and_then` method is used to chain a computation that returns an `Option` or a `Result`.
/// This can be replaced with the `?` operator, which is more concise and idiomatic.
///
/// ### Example
///
/// ```no_run
/// fn test(opt: Option<i32>) -> Option<i32> {
///     opt.and_then(|n| {
///         if n > 1 {
///             Some(n + 1)
///         } else {
///             None
///        }
///     })
/// }
/// ```
/// Use instead:
/// ```no_run
/// fn test(opt: Option<i32>) -> Option<i32> {
///     let n = opt?;
///     if n > 1 {
///         Some(n + 1)
///     } else {
///         None
///     }
/// }
/// ```
// #[clippy::version = "1.86.0"]
export const RETURN_AND_THEN: Lint = Object.freeze<Lint>({
  name: "clippy::RETURN_AND_THEN",
  default_level: "Allow",
  desc: "using `Option::and_then` or `Result::and_then` to chain a computation that returns an `Option` or a `Result`",
  edition_lint_opts: undefined,
  report_in_external_macro: true,
  future_incompatible: undefined,
  is_externally_loaded: true,
  feature_gate: undefined,
  crate_level_only: false,
  eval_always: false,
  ignore_deny_warnings: false,
  rust_version: undefined,
});
