/// ```no_run
/// let vector = vec!["hello",  "world"];
/// let output = vector.iter().map(|item| item.to_uppercase()).collect::<Vec<String>>().join("");
/// println!("{}", output);
/// ```
/// The correct use would be:
/// ```no_run
/// let vector = vec!["hello",  "world"];
/// let output = vector.iter().map(|item| item.to_uppercase()).collect::<String>();
