// rustc-lint: src/tools/clippy/clippy_lints/src/methods/mod.rs:4870 UNWRAP_USED
/// ### What it does
/// Checks for `.unwrap()` or `.unwrap_err()` calls on `Result`s and `.unwrap()` call on `Option`s.
///
/// ### Why restrict this?
/// It is better to handle the `None` or `Err` case,
/// or at least call `.expect(_)` with a more helpful message. Still, for a lot of
/// quick-and-dirty code, `unwrap` is a good choice, which is why this lint is
/// `Allow` by default.
///
/// `result.unwrap()` will let the thread panic on `Err` values.
/// Normally, you want to implement more sophisticated error handling,
/// and propagate errors upwards with `?` operator.
///
/// Even if you want to panic on errors, not all `Error`s implement good
/// messages on display. Therefore, it may be beneficial to look at the places
/// where they may get displayed. Activate this lint to do just that.
///
/// ### Examples
/// ```no_run
/// # let option = Some(1);
/// # let result: Result<usize, ()> = Ok(1);
/// option.unwrap();
/// result.unwrap();
/// ```
///
/// Use instead:
/// ```no_run
/// # let option = Some(1);
/// # let result: Result<usize, ()> = Ok(1);
/// option.expect("more helpful message");
/// result.expect("more helpful message");
/// ```
///
/// If [expect_used](#expect_used) is enabled, instead:
/// ```rust,ignore
/// # let option = Some(1);
/// # let result: Result<usize, ()> = Ok(1);
/// option?;
///
/// // or
///
/// result?;
/// ```
// #[clippy::version = "1.45.0"]
export const UNWRAP_USED: Lint = Object.freeze<Lint>({
  name: "clippy::UNWRAP_USED",
  default_level: "Allow",
  desc: "using `.unwrap()` on `Result` or `Option`, which should at least get a better message using `expect()`",
  edition_lint_opts: undefined,
  report_in_external_macro: true,
  future_incompatible: undefined,
  is_externally_loaded: true,
  feature_gate: undefined,
  crate_level_only: false,
  eval_always: false,
  ignore_deny_warnings: false,
  rust_version: undefined,
});
